from pathlib import Path
import re
p=Path('index.html');s=p.read_text(encoding='utf8');s=re.sub(r'<section class="section home-summary">.*?</section>','',s,flags=re.S)
def story(cls,kicker,title,copy,url,cta,img):
 return f'<section class="section home-story {cls}"><div class="wrap home-story-layout"><div><p class="eyebrow">{kicker}</p><h2 class="section-title">{title}</h2><p>{copy}</p><a class="btn btn-outline" href="{url}">{cta} ↗</a></div><img src="images/{img}" alt="" loading="lazy"></div></section>'
stories=story('','About Triple 7','Built in Kimberley.<br><em>Driven by people.</em>','Triple 7 Holdings Mining Division brings together responsible diamond recovery, processing and trade. Led by Daniel T. Ntsiyane, our team works across operations, engineering, geology, finance and community outreach. Our purpose is to create value, make a difference and improve lives.','about.html','Meet the company & team','team-daniel.jpg')+story('story-tint','Minerals','Resources worth<br><em>understanding.</em>','Explore natural rough and polished diamonds and gold, with clear information about each product and a direct route to our Kimberley desk. Our Minerals page also previews a wider selection of metals and gemstones as we develop the collection.','minerals.html','Explore Minerals','rough-stone.jpg')
needle='<section class="section bulk-section"';s=s.replace(needle,stories+needle,1)
consult='<article class="offer-card reveal"><div class="offer-card-image"><img src="images/hero-modican.jpg" alt="Mining operations illustrating consulting services" loading="lazy"><span>06</span></div><div class="offer-card-copy"><p class="eyebrow">Consulting</p><h3>Expertise for your next step</h3><p>Discuss mining projects, mineral requirements and operational challenges with our team to understand your options and plan the next step.</p><a class="text-link" href="about.html#consulting">Explore Consulting ↗</a></div></article>'
start=s.index('<section class="section editorial-offer"');end=s.index('</section>',start);block=s[start:end];block=block.replace('</div></div>',consult+'</div></div>') if False else block
# Insert after the last existing service article.
pos=s.rfind('</article>',start,end)+len('</article>');s=s[:pos]+consult+s[pos:]
invest=story('story-tint','Invest with Triple 7','Understand the project.<br><em>Explore the opportunity.</em>','Our investment journey starts with the company and its mine projects. Register your interest, share your profile and discuss project information, the proposed terms and supporting documents with the team. Approved investors can explore opportunities in their workspace.','investors.html','Explore Invest','hero-banner2.jpg')
s=s.replace('<section class="section on-dark">',invest+'<section class="section on-dark">',1);p.write_text(s,encoding='utf8')
p=Path('minerals.html');s=p.read_text(encoding='utf8');extras=[('Platinum','Precious metal','A preview of platinum products, with space for form, purity and assay details.','platinum'),('Silver','Precious metal','A preview of silver products for discussions around bars, grain and other forms.','silver'),('Ruby','Gemstone','A preview of ruby listings with details for colour, cut and treatment.','ruby'),('Sapphire','Gemstone','A preview of sapphire listings with space for colour, carat weight and certification.','sapphire'),('Emerald','Gemstone','A preview of emerald listings with details for origin, clarity and treatment.','emerald'),('Tanzanite','Gemstone','A preview of tanzanite listings with space for colour, cut and carat weight.','tanzanite')]
cards=''
for name,category,desc,key in extras:
 cards+=f'<article class="mineral-card mineral-mock reveal"><div class="mineral-illustration mineral-{key}" aria-hidden="true"><span class="mineral-shape"></span><span class="mock-label">Preview listing</span></div><div><p class="eyebrow">{category}</p><h2>{name}</h2><p>{desc}</p><p class="mock-note">Mock listing · availability to be confirmed.</p><a href="#inquiry" class="text-link" data-inquiry-interest="{name}">Inquire about {name} ↗</a></div></article>'
s=s.replace('</div><p class="availability-note">',cards+'</div><p class="availability-note">',1).replace('<a href="minerals.html">Minerals</a>','<a href="minerals.html" class="is-active" aria-current="page">Minerals</a>',1)
s=s.replace('<option>Gold</option>','<option>Gold</option>'+''.join(f'<option>{x[0]}</option>' for x in extras))
p.write_text(s,encoding='utf8')
p=Path('about.html');s=p.read_text(encoding='utf8')
s=s.replace('Triple 7 Holdings connects diamond mining, processing and trade from our base in Kimberley.','Triple 7 Holdings Mining Division is a South African diamond mining company built in Kimberley, with over a decade of industry experience.').replace('Our two mine projects are in the Northern Cape. Our goal is to produce high-quality large stones and build lasting relationships with the people and communities around our operations.','Our work spans responsible resource extraction, high-quality rough diamonds and the advancement of cut and polished diamonds for the global market. Ethical practices, sustainable development and community empowerment guide our approach.').replace('<span>Collaboration</span>','<span>Collaboration</span><span>Entrepreneurial Spirit</span>',1)
mission='<section class="section about-mission"><div class="wrap about-intro-layout"><div><p class="eyebrow">Vision &amp; mission</p><h2 class="section-title">Create value.<br>Make a difference.<br><em>Improve lives.</em></h2></div><div><p class="about-lead">Our purpose reaches beyond the mine.</p><p>We empower our workforce to share innovative ideas that improve our workplaces and the company. As we expand, we aim to grow alongside the communities in which we operate.</p><p>Through collaboration with local governments and communities, we invest in sustainable development initiatives that make a positive social and economic contribution.</p></div></div></section>'
ceo='<section class="section ceo-section"><div class="wrap ceo-layout"><img src="images/team-daniel.jpg" alt="Daniel T. Ntsiyane, Chief Executive Officer" loading="lazy"><div><p class="eyebrow">From the CEO</p><h2 class="section-title">Leadership with<br><em>a sense of purpose.</em></h2><p>Daniel leads a team committed to innovative, ethical practices in the diamond industry. His focus brings together community upliftment, transparency and collaboration to help shape a responsible future for mining.</p><h3>Daniel T. Ntsiyane</h3><p class="team-role">Chief Executive Officer</p><a class="text-link" href="mailto:Daniel@triple7holdings.co.za">Daniel@triple7holdings.co.za</a></div></div></section>'
teams=[('Operations','Mine recovery, engineering, geology and site delivery.',[('Larry Quma','Operations Manager',None),('Thabiso Morake','Certified Diamond Evaluator & Site Foreman',None),('Gerald Poho Marame','Head of Engineering',None),('Lerato Makgopela','Assistant Geologist',None),('Ofentse Shuping','Mining Analyst','team-ofentse.jpg'),('Revonia','Head of Procurement','team-revonia.jpg')]),('Administration','Finance, office coordination, marketing and community liaison.',[('Adiel Hollenbach','Financial Manager',None),('Rose Manuel','Head Administrator & Community Outreach',None),('Lunga Nogqala','Marketing Manager',None),('Thapelo Mahlangu','Social Media',None)])]
team='<section class="section team-section" id="team"><div class="wrap"><p class="eyebrow">Our people</p><h2 class="section-title">Meet the team.</h2><p class="team-intro">Led from Kimberley, with expertise across Operations, Administration and Legal.</p>'
for name,desc,people in teams:
 team+=f'<div class="team-group"><div class="team-group-heading"><h3>{name}</h3><p>{desc}</p></div><div class="team-grid">'
 for person,role,img in people:
  avatar=f'<img src="images/{img}" alt="{person}" loading="lazy">' if img else f'<span class="team-initials" aria-hidden="true">{"".join(n[0] for n in person.split()[:2])}</span>'
  team+=f'<article class="team-card">{avatar}<h4>{person}</h4><p>{role}</p>'+('<a href="mailto:Revonia@triple7holdings.co.za">Revonia@triple7holdings.co.za</a>' if person=='Revonia' else '')+'</article>'
 team+='</div></div>'
team+='<div class="team-legal"><h3>Legal</h3><p>Compliance, licensing and contractual oversight for mining and trade. Further team details will be added as they are published.</p></div></div></section>'
s=s.replace('<section class="section company-overview"',mission+ceo+team+'<section class="section company-overview"',1)
consultabout='<section class="section about-consulting" id="consulting"><div class="wrap about-intro-layout"><div><p class="eyebrow">Consulting</p><h2 class="section-title">Discuss the challenge.<br><em>Plan the next step.</em></h2></div><div><p class="about-lead">Bring your mining project, operational question or mineral requirement to our team.</p><p>Start with a conversation about your objectives, the information available and where you need support. Our team can discuss the scope and appropriate next steps.</p><a class="btn btn-solid" href="contact.html#inquiry">Inquire about Consulting</a></div></div></section>'
manufacture='<section class="section manufacturing-overview"><div class="wrap company-overview-grid"><article><p class="eyebrow">Manufacturing</p><h3>Cut &amp; Polish</h3><p>Rough is only the beginning. Our pathway advances selected rough diamonds into polished stones with attention to yield, brilliance and market fit.</p><a class="text-link" href="#services">Our process ↗</a></article><article><p class="eyebrow">Manufacturing</p><h3>Jewellery</h3><p>A Triple 7 diamond can continue its journey as jewellery built for real wear, from rings and necklaces to commissioned pieces.</p><a class="text-link" href="contact.html#inquiry">Discuss a commissioned piece ↗</a></article><article><p class="eyebrow">Provenance</p><h3>Trust is part of the stone</h3><p>Responsible mining, progressive rehabilitation and local conservation work sit alongside safety, skills development and transparent trade.</p><a class="text-link" href="provenance.html">Explore Provenance ↗</a></article></div></section>'
s=s.replace('<section class="section about-responsibility">',consultabout+manufacture+'<section class="section about-responsibility">',1)
partners='<section class="section-tight about-partners"><div class="wrap"><p class="eyebrow">Our network</p><h2 class="section-title">Partners in progress.</h2><div class="partner-names"><span>PAKHULA GOLD</span><span>SPIDANS</span></div><div class="office-grid"><article><h3>Kimberley</h3><p>25 Villiers St, Herlear<br>Kimberley, 8300</p></article><article><h3>Johannesburg</h3><p>West Tower, 2nd Floor, Nelson Mandela Square<br>Maude Street, Sandown<br>Johannesburg 2146, South Africa</p></article></div></div></section>'
s=s.replace('</main><footer',partners+'</main><footer',1);p.write_text(s,encoding='utf8')
